import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"A modal with a form","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/modal-form.md","filePath":"patterns/modal-form.md"}'),n={name:"patterns/modal-form.md"};function i(s,e,l,h,d,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="a-modal-with-a-form" tabindex="-1">A modal with a form <a class="header-anchor" href="#a-modal-with-a-form" aria-label="Permalink to &quot;A modal with a form&quot;">​</a></h1><p>A form in a <a href="./../components/modal">Modal</a>: the fields of one task, a check when it is sent, and one primary action.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a task that stops the work and asks for a few values: create, rename, invite, export. A single question before an action is a <a href="./../components/confirm">Confirm</a>; a form that runs a process and shows its progress is a <a href="./../workbench/process-dialog">ProcessDialog</a>; many settings that stay are a <a href="./settings">settings page</a>.</p><h2 id="parts" tabindex="-1">Parts <a class="header-anchor" href="#parts" aria-label="Permalink to &quot;Parts&quot;">​</a></h2><ul><li><a href="./../components/modal">Modal</a> with a <code>title</code> that says what the task does. Its body stacks the fields gap-md apart.</li><li>A <a href="./../components/field">Field</a> around each control: the name above, a note or an error below. The controls are <a href="./../components/text-input">TextInput</a>, <a href="./../components/select">Select</a>, <a href="./../components/textarea">Textarea</a> and the other inputs.</li><li>A <a href="./../components/checkbox">Checkbox</a> or a <a href="./../components/toggle">Toggle</a> for a yes or no, without a Field.</li><li>A <a href="./../components/banner">Banner</a> first in the body, when something about the task must be read before it is filled in.</li><li>The <code>cancel</code> and <code>primary</code> snippets, which the modal places in its <a href="./../components/footer">Footer</a>.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>One primary action, named with a verb: Create, not OK.</li><li>Check when the primary action is pressed, not on every key. Show the error in the Field of the value, with <code>error</code> on the control, and keep the modal open.</li><li>The first input takes the focus when the modal opens. Below 48rem the modal fills the screen and its actions move into the head.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/pattern-modal-form/" title="A modal with a form" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/pattern-modal-form/" target="_blank" rel="noopener">A modal with a form</a></figcaption></figure>',10)])])}const f=a(n,[["render",i]]);export{p as __pageData,f as default};
